import { useMemo, useState } from 'react';
import {
  JxChip,
  JxProgressCircle,
  JxBadge,
  JxPagination,
  JxEmptyState,
  JxButton,
} from '@jinx-ui/react';

type ProjectStatus = 'active' | 'paused' | 'over';

interface Project {
  id: string;
  name: string;
  quotaUsed: number;
  status: ProjectStatus;
}

const projects: Project[] = [
  { id: 'p1', name: 'Атлас', quotaUsed: 42, status: 'active' },
  { id: 'p2', name: 'Барвинок', quotaUsed: 88, status: 'over' },
  { id: 'p3', name: 'Вектор', quotaUsed: 15, status: 'paused' },
  { id: 'p4', name: 'Гризли', quotaUsed: 67, status: 'active' },
  { id: 'p5', name: 'Дельта', quotaUsed: 100, status: 'over' },
  { id: 'p6', name: 'Ёлка', quotaUsed: 30, status: 'paused' },
  { id: 'p7', name: 'Жасмин', quotaUsed: 54, status: 'active' },
  { id: 'p8', name: 'Зенит', quotaUsed: 92, status: 'over' },
  { id: 'p9', name: 'Икс', quotaUsed: 10, status: 'paused' },
  { id: 'p10', name: 'Йога', quotaUsed: 73, status: 'active' },
  { id: 'p11', name: 'Кактус', quotaUsed: 5, status: 'paused' },
  { id: 'p12', name: 'Лотос', quotaUsed: 99, status: 'over' },
];

const statusOptions: { value: ProjectStatus; label: string }[] = [
  { value: 'active', label: 'Активен' },
  { value: 'paused', label: 'Приостановлен' },
  { value: 'over', label: 'Превышена квота' },
];

const statusBadgeTone: Record<ProjectStatus, 'success' | 'warning' | 'danger'> = {
  active: 'success',
  paused: 'warning',
  over: 'danger',
};

const statusBadgeLabel: Record<ProjectStatus, string> = {
  active: 'Активен',
  paused: 'Приостановлен',
  over: 'Превышена квота',
};

const PAGE_SIZE = 5;

export default function ProjectQuotaPanel() {
  const [activeStatuses, setActiveStatuses] = useState<ProjectStatus[]>(
    statusOptions.map((option) => option.value),
  );
  const [page, setPage] = useState(1);

  const toggleStatus = (status: ProjectStatus) => {
    setActiveStatuses((prev) => {
      const next = prev.includes(status)
        ? prev.filter((item) => item !== status)
        : [...prev, status];
      return next;
    });
    setPage(1);
  };

  const resetFilters = () => {
    setActiveStatuses(statusOptions.map((option) => option.value));
    setPage(1);
  };

  const filteredProjects = useMemo(
    () => projects.filter((project) => activeStatuses.includes(project.status)),
    [activeStatuses],
  );

  const pageCount = Math.max(1, Math.ceil(filteredProjects.length / PAGE_SIZE));
  const currentPage = Math.min(page, pageCount);
  const visibleProjects = filteredProjects.slice(
    (currentPage - 1) * PAGE_SIZE,
    currentPage * PAGE_SIZE,
  );

  return (
    <div
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: '16px',
        maxWidth: '520px',
        padding: '16px',
        background: 'var(--jx-surface)',
        border: '1px solid var(--jx-border)',
        borderRadius: 'var(--jx-r-lg)',
        boxShadow: 'var(--jx-shadow-sm)',
      }}
    >
      <div style={{ display: 'flex', flexWrap: 'wrap', gap: '8px' }}>
        {statusOptions.map((option) => (
          <JxChip
            key={option.value}
            active={activeStatuses.includes(option.value)}
            removable={activeStatuses.includes(option.value)}
            onClick={() => toggleStatus(option.value)}
            onRemove={() => toggleStatus(option.value)}
          >
            {option.label}
          </JxChip>
        ))}
      </div>

      {visibleProjects.length === 0 ? (
        <JxEmptyState
          title="Ничего не найдено"
          message="По выбранным фильтрам нет ни одного проекта."
          action={
            <JxButton variant="primary" onClick={resetFilters}>
              Сбросить фильтры
            </JxButton>
          }
        />
      ) : (
        <>
          <div style={{ display: 'flex', flexDirection: 'column', gap: '4px' }}>
            {visibleProjects.map((project) => (
              <div
                key={project.id}
                style={{
                  display: 'flex',
                  alignItems: 'center',
                  gap: '16px',
                  padding: '12px',
                  borderBottom: '1px solid var(--jx-rule)',
                }}
              >
                <JxProgressCircle value={project.quotaUsed} showValue />
                <span
                  style={{
                    flex: 1,
                    color: 'var(--jx-text)',
                    fontFamily: 'var(--jx-font-sans)',
                  }}
                >
                  {project.name}
                </span>
                <JxBadge tone={statusBadgeTone[project.status]} dot>
                  {statusBadgeLabel[project.status]}
                </JxBadge>
              </div>
            ))}
          </div>

          <JxPagination total={pageCount} page={currentPage} onPageChange={setPage} />
        </>
      )}
    </div>
  );
}

